static NSArray * _logos_method$App$BBMediaDescRecommendUperModel$items(_LOGOS_SELF_TYPE_NORMAL BBMediaDescRecommendUperModel* _LOGOS_SELF_CONST __unused self, SEL __unused _cmd) {
    NSArray *items = _logos_orig$App$BBMediaDescRecommendUperModel$items(self, _cmd);
    if (items.count == 0) {
        return items;
    }
    NSMutableArray *filtered = [NSMutableArray array];
    for (id item in items) {
        if (NJRecommendUperItemIsAd(item)) {
            continue;
        }
        [filtered addObject:item];
    }
    if (filtered.count == items.count) {
        return items;
    }
    [self setItems:filtered];
    return filtered;
}




